        "headingPashto": "4 څپرکی: قائد اعظم محمد علي جناح رحمه الله",
        "text": "Students Learning Outcomes\\n\\nAfter completing this chapter, the students will be able to:\\n\\n• Introduce Quaid-e-Azam Muhammad Ali Jinnah as the founder of Pakistan.\\n\\n• Narrate the major events in the life of Quaid-e-Azam Muhammad Ali Jinnah (date of birth, founder of Pakistan, few major contributions and the date when he died).\\n\\nThe real name of Quaid-e-Azam was Muhammad Ali Jinnah. He was born on December 25, 1876 in Karachi.\\n\\nAfter getting his early education in Karachi, he went to England for higher studies in law. On his return to India, he started practicing law. Quaid-e-Azam started his political life in 1906. At that time India was under British occupation. He wanted Muslims and Hindus to work together to liberate India from the British. He worked a lot for the cause of Hindu Muslim unity. He soon realised that the rights of Muslims in India would not be protected after getting independence from\\n\\nthe British. Therefore, he demanded separate country for Muslims in Lahore Resolution in 1940. For this purpose, he united the Muslims of India. Muslims struggled hard for a separate country and Pakistan came into being on August 14, 1947.\\n\\nBecause of his this achievement, he is called father of the nation and founder of Pakistan. He became the first Governor General of Pakistan. He wanted to make Pakistan a strong, peaceful, prosperous and Islamic welfare state. Quaid-e-Azam Muhammad Ali Jinnah died on September 11, 1948. His tomb is in Karachi.\\n\\nQuaid-e-Azam had great qualities. He was truthful, honest, hardworking and had love for justice. His rivals also praised him. His greatest quality was his punctuality. Faith, unity and discipline are important principles given by Quaid-e-Azam. We can make Pakistan a great and developed country by acting upon Quaid-e-Azam Muhammad Ali Jinnah's principles.\\n\\nActivity\\n\\nGet more information about Quaid-e-Azam from your grandparents. Hang these information in classroom in the form of a chart.\\n\\nDo You Know?",
