    "authorInfo": "General Knowledge Grade 3, Chapter 5 - KPK Textbook Board Peshawar.",
    "text": "Students Learning Outcomes\\n\\nAfter completing this chapter, the students will be able to:\\n\\n• Introduce Allama Muhammad Iqbal as a personality who expounded the idea of Pakistan.\\n\\n• Narrate the major events in the life of Allama Muhammad Iqbal (date of birth, national poet, famous poems for children and the date when he died).\\n\\nDo you know who introduced the idea of a separate country for the Muslims of India? This idea was introduced by Allama Muhammad Iqbal. That is why he is called the dreamer of Pakistan.\\n\\nAllama Muhammad Iqbal was\\n\\nborn on November 9, 1877 in Sialkot, Punjab. He got his early education from Sialkot and MA from Government College Lahore. He got his higher education from England and Germany. Allama Iqbal was a great poet. He is called the poet of the East. Allama Iqbal wrote poems in Urdu and\\n\\nPersian. His poetry is taught in many countries of the world. He served as a teacher at Government College Lahore and also practiced law for some time. His greatest achievement as a politician was the demand of a separate country for the Muslims of India.\\n\\nDo You Know?\\n\\nAllama Muhammad\\n\\nIqbal is also called\\n\\nHakim-ul-Ummah.",
