            "urduA": "علامہ محمد اقبال ۹ نومبر ۱۸۷۷ء کو سیالکوٹ میں پیدا ہوئے۔ وہ ہمارے قومی شاعر اور عظیم مفکر تھے۔ انہوں نے ۱۹۳۰ء کے خطبہ الہ آباد میں مسلمانوں کے لیے ایک الگ خود مختار وطن کا تصور پیش کیا اور نوجوانوں کو خودی کا درس دیا۔ اس باب سے طلبہ کے علم میں اضافہ ہوتا ہے اور وہ ذمہ دار شہری بنتے ہیں۔",
