    "authorInfo": "General Knowledge Grade 3, Chapter 7 - KPK Textbook Board Peshawar.",
    "text": "Students Learning Outcomes\\n\\nAfter completing this chapter, the students will be able to:\\n\\n• Recognize that heat and light of sun help to sustain life on Earth which is the only known planet where life exists.\\n\\n• Define the term habitat.\\n\\nDescribe the different habitats, for living things (polar region, desert, forest, aquatic).\\n\\n• Name plants and animals which live in each of the different habitats.\\n\\n• Briefly introduce what an ecosystem is.\\n\\n• Identify the environmental factors (temperature, light, water) that support the life in a habitat.\\n\\n• Understand the ways plants and animals have certain features adapted to their habitat (camel, fish, polar bear, cacti, lotus, Pine tress etc).\\n\\n• Identify the ways human activities affect the natural habitats.\\n\\nIn universe Earth is the only planet where life exists. Heat and light is necessary for the maintenance of life and its biggest source is sun. This light and heat are called solar energy. Plants prepare their food by using solar energy and other living organisms depends on plants. Life is not possible without sun.\\n\\nDo you know?",
