    "text": "Food\\n\\nAfter completing this chapter, the students will be able to:\\n\\n• Recognize that plants make their own food in the presence of sunlight.\\n\\n• Recognize that different animals eat different kinds of food.\\n\\n• Identify certain food groups as fruits, vegetables, grains, dairy product, meat and dry fruits.\\n\\n• Define a balanced diet.\\n\\n• Recognize that healthy living requires eating a balanced diet, keeping clean, sleeping well and exercise regularly.\\n\\n• Identify the ways to get sufficient exercise to stay healthy.\\n\\nFood\\n\\nLiving organisms need energy for their life. They get energy from food. Therefore, food is the basic need of all living organisms. Plants prepare their food in the presence of sunlight, while the remaining organisms depend directly or indirectly on plants for their food.\\n\\nAlso understand!\\n\\nThe process in which plants prepare their food in the presence of sunlight is called photosynthesis.",
