            "urduA": "ہر وہ چیز جو وزن رکھتی ہے اور جگہ گھیرتی ہے مادہ کہلاتی ہے۔ مادے کی تین بنیادی حالتیں ہیں: ٹھوس (جیسے پتھر، لکڑی)، مائع (جیسے پانی، دودھ)، اور گیس (جیسے ہوا، بھاپ)۔ اس باب سے طلبہ کے علم میں اضافہ ہوتا ہے اور وہ ذمہ دار شہری بنتے ہیں۔",
