        "english": "Students Learning Outcomes\\n\\nAfter completing this chapter, the students will be able to:\\n\\nRecognize that present time is different from the past in terms of living style, food, communication, clothes etc.\\n\\nIdentify how schools, communities and transportation have changed over time (from the given pictures)\\n\\n• Sequence events in a narrative in chronological order.\\n\\nIt is clear from the information obtained from various sources that the life style, dress, food, source of transportation and methods of communication of people of old age were completely different from the present age. They lived in caves. Plants, fruits and uncooked meat were their food. They made their tools from stones and animals bones.\\n\\nThink and Share Why people of stone age ate uncooked meat?\\n\\nWith the passage of time man learned making of fire and cooking food. To meet their needs of food man started cultivating crops and petting animals. Invention of wheel and discovery of metals paved the way for human development. Due to continuous struggle of human beings the present life is very comfortable and safe than the past.\\n\\nLets compare the ancient world with the present with the help of\\n\\npictures.\\n\\nPast\\n\\nPresent"
