            "question": "Explain in detail the main teachings of Chapter 13: Changing World.",
            "answer": "In Chapter 13 (Changing World), students learn about بدلتی ہوئی دنیا. ہماری دنیا وقت کے ساتھ ساتھ تبدیل ہو رہی ہے۔ قدیم زمانے میں لوگ پیدل سفر کرتے تھے اور ہاتھ سے کام کرتے تھے۔ آج تیز رفتار گاڑیاں، ہوائی جہاز اور جدید مواصلاتی ذرائع دستیاب ہیں۔ By understanding these principles, students develop strong character, scientific knowledge, and civic awareness.",
