        "english": "Students Learning Outcomes\\n\\nAfter completing this chapter, the students will be able to:\\n\\n• Describe what an invention is.\\n\\n• Identify major recent inventions (e.g. aeroplane, computer, internet etc.).\\n\\n• Analyze recent inventions (electricity, computers, phone and internet etc.) have changed the lives of people.\\n\\nInventions\\n\\nWe use different things, instruments and machines to make our daily life comfortable. These things were not available in the past. Human life was difficult at that time. Human beings started making new things to bring comfort to their lives. For example, they hunted animals with stones. It was hard and dangerous. So they made bow and arrow and other weapons. This made hunting of animals easy. Invention means making a thing which does not exist before. A person who makes a new thing is called an inventor. Every invention is important in its own capacity. It helps in doing work quickly and easily. The work requires less labour. Inventions have made our life easier and less tiring. Journeys which took days, months and years are now travelled in hours. Today human beings can control natural disasters and diseases better than before. Messages can be sent immediately to any part of the world.\\n\\nS.No\\n\\nActivity\\n\\nMake a list of your favourite inventions.\\n\\nInvention\\n\\nInventor"
