    "authorInfo": "General Knowledge Grade 3, Chapter 15 - KPK Textbook Board Peshawar.",
    "text": "Students Learning Outcomes\\n\\nAfter completing this chapter, the students will be able to:\\n\\n• Define tool as in instrument to make people's work easier.\\n\\n• Name and identify different forms of simple machines (inclined plane, lever, pulley, wheel and axel, wedge, screw).\\n\\n• Recognize that push and pull moves things fast or slow (push and pull as a force).\\n\\n• Recognize from pictures of the past that force applied by humans and animals moved vehicles (Tonga, bullock cart, bicycle, pushcart) while today vehicles are moved by machines (bus, motorcycle and car etc.).\\n\\n• Recognize that greater the force, the greater the change in the motion of an object.\\n\\n• Observe and describe how motion of objects can be changed by applying force (speed up, slow down, stop, change direction etc.)\\n\\nTools\\n\\nIn the beginning man did everything with hands because he had no tools. Then man started making tools from stones, wood and bones of animals. They were very simple. They were improved with the passage of time. Tools making from other metals started too. This completely changed human life.\\n\\nTool is a thing which is used to make certain task easier e.g. hammer, saw, axe, and plier etc.\\n\\nPlier",
