    "text": "Safety\\n\\nAfter completing this chapter, the students will be able to:\\n\\nRecognize the need of personal safety.\\n\\n• Understand the risk and danger associated with the use of electric appliances/sharp objects/fire.\\n\\n• Practice safety measures while using electric appliances.\\n\\n• List the various hazards they can face at home. (bare wires, damaged roof, broken glass, fire, scissor etc.).\\n\\n• Understand the ways of being careful and staying safe.\\n\\n• Identify some common disasters and ways to stay safe.\\n\\n• Understand that they should not hide anything from their parents/ teachers/guardians to stay safe from any unexpected situation.\\n\\nSafety\\n\\nTools, machines and sources of energy e.g. electricity, gas have become part of our daily life. It is difficult to live without them. No doubt these tools and machines have made our lives comfortable but they also have created dangers and problems for us. Therefore, safety is necessary for us.\\n\\nActivity",
